"""Build six static pages with bilingual copy. No framework or server required."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
SCHOLAR='https://scholar.google.com/citations?user=uld736gAAAAJ'
PROFILE='https://new.skoltech.ru/en/persons/ilya-chepkasov'
def t(ru,en,tag='span',cls=''):
    return f'<{tag} class="{cls}" data-ru="{e(ru,quote=True)}" data-en="{e(en,quote=True)}">{e(ru)}</{tag}>'
def link(url,ru,en,cls='text-link'):
    ext=' target="_blank" rel="noopener noreferrer"' if url.startswith('https:') else ''
    return f'<a class="{cls}" href="{e(url,quote=True)}"{ext}>{t(ru,en)} <span aria-hidden="true">↗</span></a>'
NAV=[('index.html','Главная','Home'),('research.html','Исследования','Research'),('publications.html','Публикации','Publications'),('activities.html','Деятельность','Activities'),('cv.html','Биография','Biography'),('contact.html','Контакты','Contact')]
def page(file,title_ru,title_en,body,home=False):
    nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{t(ru,en)}</a>' for f,ru,en in NAV)
    head=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Илья Чепкасов — старший научный сотрудник Сколтеха. Вычислительное материаловедение, нанокатализ и материалы для энергетики."><title>{title_ru} — Илья Чепкасов</title><link rel="icon" href="assets/images/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/css/styles.css"><script src="assets/js/publications-data.js" defer></script><script src="assets/js/main.js" defer></script></head><body data-title-ru="{title_ru} — Илья Чепкасов" data-title-en="{title_en} — Ilya Chepkasov" class="{'home' if home else 'inner'}"><a class="skip" href="#main">{t('К содержанию','Skip to content')}</a><header class="site-header"><div class="header-inner"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">IC<span>·</span></span><span class="brand-name">{t('Илья Чепкасов','Ilya Chepkasov')}</span></a><button id="menu-toggle" class="menu-toggle" aria-controls="nav" aria-expanded="false">{t('Меню','Menu')}</button><nav id="nav" aria-label="Навигация" data-aria-ru="Навигация" data-aria-en="Main navigation">{nav}</nav><div class="language" role="group" aria-label="Язык / Language"><button data-lang="ru" aria-pressed="true">RU</button><span>/</span><button data-lang="en" aria-pressed="false">EN</button></div></div></header>'''
    footer=f'''<footer><div class="container footer-inner"><div><a href="index.html">{t('Илья Чепкасов','Ilya Chepkasov')}</a><p>{t('Вычислительное материаловедение · Сколтех','Computational materials science · Skoltech')}</p></div><div class="footer-links">{link(SCHOLAR,'Google Scholar','Google Scholar')}{link('https://orcid.org/0000-0001-8376-2999','ORCID','ORCID')}<a href="mailto:I.Chepkasov@skoltech.ru">Email ↗</a></div><span class="copyright">© 2026</span></div></footer></body></html>'''
    (ROOT/file).write_text(head+f'<main id="main">{body}</main>'+footer,encoding='utf-8')
def heading(n,ru,en,desc_ru,desc_en):
    return f'<section class="page-head container"><div class="section-index">{n} / {t("Научный профиль","Scientific profile")}</div>{t(ru,en,"h1")}{t(desc_ru,desc_en,"p","lede")}</section>'
FIELDS=[
('01','Нанокатализ','Nanocatalysis','Металлические и биметаллические наночастицы, структуры ядро–оболочка. Связь состава и атомного строения с адсорбцией и каталитическими свойствами.','Metallic and bimetallic nanoparticles, core–shell structures. Connecting composition and atomic structure with adsorption and catalytic properties.','AuCu · PdIr · TM@Pt','10.1016/j.mtener.2025.102130'),
('02','Материалы для аккумуляторов','Battery materials','Аноды на основе углерода и полиароматических углеводородов, твердотельные электролиты. Интеркаляция щелочных металлов и перенос ионов.','Carbon and polyaromatic hydrocarbon anodes, solid-state electrolytes. Alkali-metal intercalation and ion transport.','Li / Na / K · PAH · Li₃MX₆','10.1016/j.pmatsci.2026.101713'),
('03','Двумерные материалы','Two-dimensional materials','Графен, MoS₂ и низкоразмерные гетероструктуры. Электронные свойства, устойчивость и взаимодействие с атомами и молекулами.','Graphene, MoS₂ and low-dimensional heterostructures. Electronic properties, stability and interactions with atoms and molecules.','Graphene · MoS₂ · V₃S₄','10.1021/acs.jpcc.2c03749'),
('04','Термоэлектрики и дефекты','Thermoelectrics & defects','Легированные материалы на основе PbTe. Влияние собственных дефектов на механические свойства и устойчивость функциональных материалов.','Doped PbTe-based materials. The role of intrinsic defects in mechanical properties and the stability of functional materials.','PbTe · Defects · Mechanics','10.1039/d5ta00823a'),
('05','Атомистическое моделирование','Atomistic modeling','Расчеты из первых принципов, молекулярная динамика, предсказание структуры и межатомные потенциалы машинного обучения.','First-principles calculations, molecular dynamics, structure prediction and machine-learning interatomic potentials.','DFT · MD · USPEX · MLIP','10.1039/d5ta00823a')]
def fields(full=False):
    result=''
    for n,ru,en,dr,de,tags,doi in FIELDS:
        result+=f'<article class="field"><span class="field-number">{n}</span><div>{t(ru,en,"h3")}{t(dr,de,"p")}<span class="tags">{tags}</span>'+(link('https://doi.org/'+doi,'Публикация по теме','Related publication') if full else '')+'</div></article>'
    return result
home=f'''<section class="hero container"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> {t('Сколтех · Вычислительное материаловедение','Skoltech · Computational materials science')}</div><h1>{t('Илья','Ilya')}<br>{t('Чепкасов','Chepkasov')}</h1>{t('Структура. Свойства. Материалы.','Structure. Properties. Materials.','p','hero-statement')}{t('Старший научный сотрудник, кандидат физико-математических наук. Исследую материалы на атомном уровне — от нанокатализаторов до систем хранения энергии.','Senior Research Scientist, PhD in condensed matter physics. Exploring materials at the atomic scale — from nanocatalysts to energy storage systems.','p','hero-bio')}<div class="hero-actions">{link('research.html','Исследования','Explore research','button')}{link(SCHOLAR,'Google Scholar','Google Scholar')}</div><div class="hero-methods">DFT <span>·</span> Molecular Dynamics <span>·</span> Machine Learning</div></div><figure class="portrait"><img src="assets/images/portrait.jpg" alt="Илья Чепкасов" data-alt-ru="Илья Чепкасов" data-alt-en="Ilya Chepkasov" width="640" height="640" fetchpriority="high"><figcaption><span>ILYA V. CHEPKASOV</span><span>{t('Научный профиль','Research profile')} / 01</span></figcaption></figure></section><section class="intro-strip"><div class="container"><p>{t('От атомного строения','From atomic structure')}<br>{t('к функциональным материалам.','to functional materials.')}</p><div>{t('Расчеты из первых принципов и молекулярная динамика помогают понять, как состав, структура и дефекты определяют свойства материала. Исследования объединяют физику наночастиц, катализ и материалы для энергетики.','First-principles calculations and molecular dynamics help explain how composition, structure and defects determine material properties. This research brings together nanoparticle physics, catalysis and energy materials.','p')}{link('cv.html','Научный путь','Academic journey')}</div></div></section><section class="section container"><div class="section-heading"><div><div class="section-index">01 / {t('Исследования','Research')}</div>{t('Области работы','Research directions','h2')}</div>{link('research.html','Подробнее','Explore all')}</div><div class="fields-grid">{fields()}</div></section><section class="featured-section"><div class="container"><div class="section-heading"><div><div class="section-index">02 / {t('В фокусе','In focus')}</div>{t('Нанокатализ на атомном уровне','Nanocatalysis at the atomic scale','h2')}</div><span class="issue">Small · 2025</span></div><div class="featured"><figure><img src="assets/images/pt-carbon.jpg" alt="Схема Pt/C катализаторов на азотированном углеродном носителе" data-alt-ru="Схема Pt/C катализаторов на азотированном углеродном носителе" data-alt-en="Pt/C catalysts on nitrogen-doped carbon support" width="1280" height="489" loading="lazy"><figcaption>{t('Иллюстрация к работе о Pt/C катализаторах и азотированном углеродном носителе.','Illustration from the study of Pt/C catalysts and nitrogen-doped carbon support.')}</figcaption></figure><div>{t('Как носитель влияет на свойства платины','How the support affects platinum','h3')}{t('Совместное исследование структуры и электрохимических свойств Pt/C катализаторов: экспериментальная характеризация и атомистическое моделирование.','A joint study of the structure and electrochemical properties of Pt/C catalysts, combining experimental characterization and atomistic modeling.','p')}{link('https://doi.org/10.1002/smll.202510144','Читать публикацию','Read the paper')}{link('publications.html','Все публикации','All publications')}</div></div></div></section><section class="section container"><div class="section-heading"><div><div class="section-index">03 / {t('Избранное','Selected work')}</div>{t('Последние обзоры','Recent reviews','h2')}</div>{link('publications.html?type=review','Все обзоры','All reviews')}</div><div class="review-grid" id="selected-reviews"></div></section>'''
